import sys

def main():
    lines = sys.stdin.read().strip().split()
    if not lines:
        return

    s = lines[0]
    r = int(lines[1])
    n = int(lines[2])

    current = s
    for _ in range(r):
        next_s = []
        for char in current:
            if char == '0':
                next_s.append('0')
                next_s.append('1')
            else:
                next_s.append('1')
                next_s.append('0')
        current = "".join(next_s)

    print(current[n])

if __name__ == "__main__":
    main()
